SELECT COUNT(*) AS user_count
FROM (
  SELECT DISTINCT user_id FROM comments WHERE user_id IS NOT NULL
) c
WHERE c.user_id NOT IN (SELECT user_id FROM posts_questions WHERE user_id IS NOT NULL)
  AND c.user_id NOT IN (SELECT user_id FROM posts_answers WHERE user_id IS NOT NULL);

SELECT ROUND(100.0 * SUM(CASE WHEN (julianday(a.creation_date) - julianday(q.creation_date)) * 24 <= 1 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_answers_within_one_hour
FROM posts_answers a
JOIN posts_questions q ON a.parent_id = q.post_id;

SELECT ROUND(100.0 * SUM(CASE WHEN (julianday(a.creation_date) - julianday(q.creation_date)) * 24 <= 1 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_within_hour
FROM posts_answers a
JOIN posts_questions q ON a.parent_id = q.post_id;

SELECT * FROM (SELECT 'longest' AS kind, c.comment_id, c.user_id, u.display_name, LENGTH(c.body) AS comment_length FROM comments c LEFT JOIN users u ON u.user_id = c.user_id WHERE c.body IS NOT NULL ORDER BY LENGTH(c.body) DESC LIMIT 1)
UNION ALL
SELECT * FROM (SELECT 'shortest' AS kind, c.comment_id, c.user_id, u.display_name, LENGTH(c.body) AS comment_length FROM comments c LEFT JOIN users u ON u.user_id = c.user_id WHERE c.body IS NOT NULL ORDER BY LENGTH(c.body) ASC LIMIT 1);

SELECT ROUND(100.0 * SUM(CASE WHEN (julianday(a.creation_date) - julianday(q.creation_date)) * 24 <= 1 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_within_hour
FROM posts_answers a
JOIN posts_questions q ON a.parent_id = q.post_id;
